sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	var name = current.name.toString().trim(); 
    var city = current.city.toString().trim();    
    var state = current.state.toString().trim();   

    // Verifica se já existe uma base com o mesmo nome
    var grNome = new GlideRecord('x_1590789_bases_base_registration');
    grNome.addQuery('name', name);
    grNome.addQuery('sys_id', '!=', current.sys_id); // Evita erro ao atualizar o próprio registro
    grNome.query();

    if (grNome.hasNext()) {
        gs.addErrorMessage('Já existe uma base com este nome.');
        current.setAbortAction(true);
        return;
    }

    // Verifica se já existe uma base com a mesma cidade + estado
    var grCidadeEstado = new GlideRecord('x_1590789_bases_base_registration');
    grCidadeEstado.addQuery('city', city);
    grCidadeEstado.addQuery('state', state);
    grCidadeEstado.addQuery('sys_id', '!=', current.sys_id);
    grCidadeEstado.query();

    if (grCidadeEstado.hasNext()) {
        gs.addErrorMessage('Já existe uma base cadastrada nesta cidade e estado.');
        current.setAbortAction(true);
        return;
    }

	if(current.isNewRecord){
		current.setValue('available_spaces',current.getValue('maximum_capacity') -1);
	}


})(current, previous);
